INSERT INTO verses (translation_id, book_id, chapter, verse, text, words_of_jesus) VALUES
('rv1909','GEN',1,1,'EN el principio crió Dios los cielos y la tierra.',NULL),
('rv1909','GEN',1,2,'Y la tierra estaba desordenada y vacía, y las tinieblas estaban sobre la haz del abismo, y el Espíritu de Dios se movía sobre la haz de las aguas.',NULL),
('rv1909','GEN',1,3,'Y dijo Dios: Sea la luz: y fué la luz.',NULL),
('rv1909','GEN',1,4,'Y vió Dios que la luz era buena: y apartó Dios la luz de las tinieblas.',NULL),
('rv1909','GEN',1,5,'Y llamó Dios á la luz Día, y á las tinieblas llamó Noche: y fué la tarde y la mañana un día.',NULL),
('rv1909','GEN',1,6,'Y dijo Dios: Haya expansión en medio de las aguas, y separe las aguas de las aguas.',NULL),
('rv1909','GEN',1,7,'E hizo Dios la expansión, y apartó las aguas que estaban debajo de la expansión, de las aguas que estaban sobre la expansión: y fué así.',NULL),
('rv1909','GEN',1,8,'Y llamó Dios á la expansión Cielos: y fué la tarde y la mañana el día segundo.',NULL),
('rv1909','GEN',1,9,'Y dijo Dios: Júntense las aguas que [están] debajo de los cielos en un lugar, y descúbrase la seca: y fué así.',NULL),
('rv1909','GEN',1,10,'Y llamó Dios á la seca Tierra, y á la reunión de las aguas llamó Mares: y vió Dios que era bueno.',NULL),
('rv1909','GEN',1,11,'Y dijo Dios: Produzca la tierra hierba verde, hierba que dé simiente; árbol de fruto que dé fruto según su género, que su simiente esté en él, sobre la tierra: y fué así.',NULL),
('rv1909','GEN',1,12,'Y produjo la tierra hierba verde, hierba que da simiente según su naturaleza, y árbol que da fruto, cuya simiente está en él, según su género: y vió Dios que era bueno.',NULL),
('rv1909','GEN',1,13,'Y fué la tarde y la mañana el día tercero.',NULL),
('rv1909','GEN',1,14,'Y dijo Dios: Sean lumbreras en la expansión de los cielos para apartar el día y la noche: y sean por señales, y para las estaciones, y para días y años;',NULL),
('rv1909','GEN',1,15,'Y sean por lumbreras en la expansión de los cielos para alumbrar sobre la tierra: y fué así.',NULL),
('rv1909','GEN',1,16,'E hizo Dios las dos grandes lumbreras; la lumbrera mayor para que señorease en el día, y la lumbrera menor para que señorease en la noche: [hizo] también las estrellas.',NULL),
('rv1909','GEN',1,17,'Y púsolas Dios en la expansión de los cielos, para alumbrar sobre la tierra,',NULL),
('rv1909','GEN',1,18,'Y para señorear en el día y en la noche, y para apartar la luz y las tinieblas: y vió Dios que era bueno.',NULL),
('rv1909','GEN',1,19,'Y fué la tarde y la mañana el día cuarto.',NULL),
('rv1909','GEN',1,20,'Y dijo Dios: Produzcan las aguas reptil de ánima viviente, y aves que vuelen sobre la tierra, en la abierta expansión de los cielos.',NULL),
('rv1909','GEN',1,21,'Y crió Dios las grandes ballenas, y toda cosa viva que anda arrastrando, que las aguas produjeron según su género, y toda ave alada según su especie: y vió Dios que era bueno.',NULL),
('rv1909','GEN',1,22,'Y Dios los bendijo diciendo: Fructificad y multiplicad, y henchid las aguas en los mares, y las aves se multipliquen en la tierra.',NULL),
('rv1909','GEN',1,23,'Y fué la tarde y la mañana el día quinto.',NULL),
('rv1909','GEN',1,24,'Y dijo Dios: Produzca la tierra seres vivientes según su género, bestias y serpientes y animales de la tierra según su especie: y fué así.',NULL),
('rv1909','GEN',1,25,'E hizo Dios animales de la tierra según su género, y ganado según su género, y todo animal que anda arrastrando sobre la tierra según su especie: y vió Dios que era bueno.',NULL),
('rv1909','GEN',1,26,'Y dijo Dios: Hagamos al hombre á nuestra imagen, conforme á nuestra semejanza; y señoree en los peces de la mar, y en las aves de los cielos, y en las bestias, y en toda la tierra, y en todo animal que anda arrastrando sobre la tierra.',NULL),
('rv1909','GEN',1,27,'Y crió Dios al hombre á su imagen, á imagen de Dios lo crió; varón y hembra los crió.',NULL),
('rv1909','GEN',1,28,'Y los bendijo Dios; y díjoles Dios: Fructificad y multiplicad, y henchid la tierra, y sojuzgadla, y señoread en los peces de la mar, y en las aves de los cielos, y en todas las bestias que se mueven sobre la tierra.',NULL),
('rv1909','GEN',1,29,'Y dijo Dios: He aquí que os he dado toda hierba que da simiente, que está sobre la haz de toda la tierra; y todo árbol en que hay fruto de árbol que da simiente, seros ha para comer.',NULL),
('rv1909','GEN',1,30,'Y á toda bestia de la tierra, y á todas las aves de los cielos, y á todo lo que se mueve sobre la tierra, en que hay vida, toda hierba verde [les será] para comer: y fué así.',NULL),
('rv1909','GEN',1,31,'Y vió Dios todo lo que había hecho, y he aquí que era bueno en gran manera. Y fué la tarde y la mañana el día sexto.',NULL),
('rv1909','PSA',23,1,'Salmo de David. JEHOVÁ es mi pastor; nada me faltará.',NULL),
('rv1909','PSA',23,2,'En lugares de delicados pastos me hará yacer: junto á aguas de reposo me pastoreará.',NULL),
('rv1909','PSA',23,3,'Confortará mi alma; guiaráme por sendas de justicia por amor de su nombre.',NULL),
('rv1909','PSA',23,4,'Aunque ande en valle de sombra de muerte, no temeré mal alguno; porque tú estarás conmigo: tu vara y tu cayado me infundirán aliento.',NULL),
('rv1909','PSA',23,5,'Aderezarás mesa delante de mí, en presencia de mis angustiadores: ungiste mi cabeza con aceite: mi copa está rebosando.',NULL),
('rv1909','PSA',23,6,'Ciertamente el bien y la misericordia me seguirán todos los días de mi vida: y en la casa de Jehová moraré por largos días.',NULL),
('rv1909','PSA',117,1,'ALABAD á Jehová, naciones todas; pueblos todos, alabadle.',NULL),
('rv1909','PSA',117,2,'Porque ha engrandecido sobre nosotros su misericordia; y la verdad de Jehová [es] para siempre. Aleluya.',NULL),
('rv1909','MAT',11,1,'Y FUÉ, que acabando Jesús de dar mandamientos á sus doce discípulos, se fué de allí á enseñar y á predicar en las ciudades de ellos.',NULL),
('rv1909','MAT',11,2,'Y oyendo Juan en la prisión los hechos de Cristo, le envió dos de sus discípulos,',NULL),
('rv1909','MAT',11,3,'Diciendo: ¿Eres tú aquél que había de venir, ó esperaremos á otro?',NULL),
('rv1909','MAT',11,4,'Y respondiendo Jesús, les dijo: Id, y haced saber á Juan las cosas que oís y veis:',NULL),
('rv1909','MAT',11,5,'Los ciegos ven, y los cojos andan; los leprosos son limpiados, y los sordos oyen; los muertos son resucitados, y á los pobres es anunciado el evangelio.',NULL),
('rv1909','MAT',11,6,'Y bienaventurado es el que no fuere escandalizado en mí.',NULL),
('rv1909','MAT',11,7,'E idos ellos, comenzó Jesús á decir de Juan á las gentes: ¿Qué salisteis á ver al desierto? ¿una caña que es meneada del viento?',NULL),
('rv1909','MAT',11,8,'Mas ¿qué salisteis á ver? ¿un hombre cubierto de delicados [vestidos]? He aquí, los que traen [vestidos] delicados, en las casas de los reyes están.',NULL),
('rv1909','MAT',11,9,'Mas ¿qué salisteis á ver? ¿un profeta? También os digo, y más que profeta.',NULL),
('rv1909','MAT',11,10,'Porque éste es de quien está escrito: He aquí, yo envío mi mensajero delante de tu faz, que aparejará tu camino delante de ti.',NULL),
('rv1909','MAT',11,11,'De cierto os digo, [que] no se levantó entre los que nacen de mujeres otro mayor que Juan el Bautista; mas el que es muy más pequeño en el reino de los cielos, mayor es que él.',NULL),
('rv1909','MAT',11,12,'Desde los días de Juan el Bautista hasta ahora, al reino de los cielos se hace fuerza, y los valientes lo arrebatan.',NULL),
('rv1909','MAT',11,13,'Porque todos los profetas y la ley hasta Juan profetizaron.',NULL),
('rv1909','MAT',11,14,'Y si queréis recibir, él es aquel Elías que había de venir.',NULL),
('rv1909','MAT',11,15,'El que tiene oídos para oir, oiga.',NULL),
('rv1909','MAT',11,16,'Mas ¿á quién compararé esta generación? Es semejante á los muchachos que se sientan en las plazas, y dan voces á sus compañeros,',NULL),
('rv1909','MAT',11,17,'Y dicen: Os tañimos flauta, y no bailasteis; os endechamos, y no lamentasteis.',NULL),
('rv1909','MAT',11,18,'Porque vino Juan, que ni comía ni bebía, y dicen: Demonio tiene.',NULL),
('rv1909','MAT',11,19,'Vino el Hijo del hombre, que come y bebe, y dicen: He aquí un hombre comilón, y bebedor de vino, amigo de publicanos y de pecadores. Mas la sabiduría es justificada por sus hijos.',NULL),
('rv1909','MAT',11,20,'Entonces comenzó á reconvenir á las ciudades en las cuales habían sido hechas muy muchas de sus maravillas, porque no se habían arrepentido, [diciendo]:',NULL),
('rv1909','MAT',11,21,'¡Ay de ti, Corazín! ¡Ay de ti, Bethsaida! porque si en Tiro y en Sidón fueran hechas las maravillas que han sido hechas en vosotras, en otro tiempo se hubieran arrepentido en saco y en ceniza.',NULL),
('rv1909','MAT',11,22,'Por tanto os digo, [que] á Tiro y á Sidón será más tolerable [el castigo] en el día del juicio, que á vosotras.',NULL),
('rv1909','MAT',11,23,'Y tú, Capernaum, que eres levantada hasta el cielo, hasta los infiernos serás abajada; porque si en los de Sodoma fueran hechas las maravillas que han sido hechas en ti, hubieran quedado hasta el día de hoy.',NULL),
('rv1909','MAT',11,24,'Por tanto os digo, [que] á la tierra de los de Sodoma será más tolerable [el castigo] en el día del juicio, que á ti.',NULL),
('rv1909','MAT',11,25,'En aquel tiempo, respondiendo Jesús, dijo: Te alabo, Padre, Señor del cielo y de la tierra, que hayas escondido estas cosas de los sabios y de los entendidos, y las hayas revelado á los niños.',NULL),
('rv1909','MAT',11,26,'Así, Padre, pues que así agradó en tus ojos.',NULL),
('rv1909','MAT',11,27,'Todas las cosas me son entregadas de mi Padre: y nadie conoció al Hijo, sino el Padre; ni al Padre conoció alguno, sino el Hijo, y aquel á quien el Hijo [lo] quisiere revelar.',NULL),
('rv1909','MAT',11,28,'Venid á mí todos los que estáis trabajados y cargados, que yo os haré descansar.',NULL),
('rv1909','MAT',11,29,'Llevad mi yugo sobre vosotros, y aprended de mí, que soy manso y humilde de corazón; y hallaréis descanso para vuestras almas.',NULL),
('rv1909','MAT',11,30,'Porque mi yugo es fácil, y ligera mi carga.',NULL),
('rv1909','MAT',17,1,'Y DESPUÉS de seis días, Jesús toma á Pedro, y á Jacobo, y á Juan su hermano, y los lleva aparte á un monte alto:',NULL),
('rv1909','MAT',17,2,'Y se transfiguró delante de ellos; y resplandeció su rostro como el sol, y sus vestidos fueron blancos como la luz.',NULL),
('rv1909','MAT',17,3,'Y he aquí les aparecieron Moisés y Elías, hablando con él.',NULL),
('rv1909','MAT',17,4,'Y respondiendo Pedro, dijo á Jesús: Señor, bien es que nos quedemos aquí: si quieres, hagamos aquí tres pabellones: para ti uno, y para Moisés otro, y otro para Elías.',NULL),
('rv1909','MAT',17,5,'Y estando aún él hablando, he aquí una nube de luz [que] los cubrió; y he aquí una voz de la nube, que dijo: Este es mi Hijo amado, en el cual tomo contentamiento: á él oid.',NULL),
('rv1909','MAT',17,6,'Y oyendo esto los discípulos, cayeron sobre sus rostros, y temieron en gran manera.',NULL),
('rv1909','MAT',17,7,'Entonces Jesús llegando, los tocó, y dijo: Levantaos, y no temáis.',NULL),
('rv1909','MAT',17,8,'Y alzando ellos sus ojos, á nadie vieron, sino á solo Jesús.',NULL),
('rv1909','MAT',17,9,'Y como descendieron del monte, les mandó Jesús, diciendo: No digáis á nadie la visión, hasta que el Hijo del hombre resucite de los muertos.',NULL),
('rv1909','MAT',17,10,'Entonces sus discípulos le preguntaron, diciendo: ¿Por qué dicen pues los escribas que es menester que Elías venga primero?',NULL),
('rv1909','MAT',17,11,'Y respondiendo Jesús, les dijo: A la verdad, Elías vendrá primero, y restituirá todas las cosas.',NULL),
('rv1909','MAT',17,12,'Mas os digo, que ya vino Elías, y no le conocieron; antes hicieron en él todo lo que quisieron: así también el Hijo del hombre padecerá de ellos.',NULL),
('rv1909','MAT',17,13,'Los discípulos entonces entendieron, que les habló de Juan el Bautista.',NULL),
('rv1909','MAT',17,14,'Y como ellos llegaron al gentío, vino á él un hombre hincándosele de rodillas,',NULL),
('rv1909','MAT',17,15,'Y diciendo: Señor, ten misericordia de mi hijo, que es lunático, y padece malamente; porque muchas veces cae en el fuego, y muchas en el agua.',NULL),
('rv1909','MAT',17,16,'Y le he presentado á tus discípulos, y no le han podido sanar.',NULL),
('rv1909','MAT',17,17,'Y respondiendo Jesús, dijo: ¡Oh generación infiel y torcida! ¿hasta cuándo tengo de estar con vosotros? ¿hasta cuándo os tengo de sufrir? traédmele acá.',NULL),
('rv1909','MAT',17,18,'Y Jesús le reprendió, y salió el demonio de él; y el mozo fué sano desde aquella hora.',NULL),
('rv1909','MAT',17,19,'Entonces, llegándose los discípulos á Jesús, aparte, dijeron: ¿Por qué nosotros no lo pudimos echar fuera?',NULL),
('rv1909','MAT',17,20,'Y Jesús les dijo: Por vuestra incredulidad; porque de cierto os digo, que si tuviereis fe como un grano de mostaza, diréis á este monte: Pásate de aquí allá: y se pasará: y nada os será imposible.',NULL),
('rv1909','MAT',17,21,'Mas este linaje no sale sino por oración y ayuno.',NULL),
('rv1909','MAT',17,22,'Y estando ellos en Galilea, Jesús les dijo: El Hijo del hombre será entregado en manos de hombres,',NULL),
('rv1909','MAT',17,23,'Y le matarán; mas al tercer día resucitará. Y ellos se entristecieron en gran manera.',NULL),
('rv1909','MAT',17,24,'Y como llegaron á Capernaum, vinieron á Pedro los que cobraban las dos dracmas, y dijeron: ¿Vuestro Maestro no paga las dos dracmas?',NULL),
('rv1909','MAT',17,25,'El dice: Sí. Y entrando él en casa, Jesús le habló antes, diciendo: ¿Qué te parece, Simón? Los reyes de la tierra, ¿de quién cobran los tributos ó el censo? ¿de sus hijos ó de los extraños?',NULL),
('rv1909','MAT',17,26,'Pedro le dice: De los extraños. Jesús le dijo: Luego los hijos son francos.',NULL),
('rv1909','MAT',17,27,'Mas porque no los escandalicemos, ve á la mar, y echa el anzuelo, y el primer pez que viniere, tómalo, y abierta su boca, hallarás un estatero: tómalo, y dáselo por mí y por ti.',NULL),
('rv1909','JHN',3,1,'Y HABÍA un hombre de los Fariseos que se llamaba Nicodemo, príncipe de los Judíos.',NULL),
('rv1909','JHN',3,2,'Este vino á Jesús de noche, y díjole: Rabbí, sabemos que has venido de Dios por maestro; porque nadie puede hacer estas señales que tú haces, si no fuere Dios con él.',NULL),
('rv1909','JHN',3,3,'Respondió Jesús, y díjole: De cierto, de cierto te digo, que el que no naciere otra vez, no puede ver el reino de Dios.',NULL),
('rv1909','JHN',3,4,'Dícele Nicodemo: ¿Cómo puede el hombre nacer siendo viejo? ¿puede entrar otra vez en el vientre de su madre, y nacer?',NULL),
('rv1909','JHN',3,5,'Respondió Jesús: De cierto, de cierto te digo, que el que no naciere de agua y del Espíritu, no puede entrar en el reino de Dios.',NULL),
('rv1909','JHN',3,6,'Lo que es nacido de la carne, carne es; y lo que es nacido del Espíritu, espíritu es.',NULL),
('rv1909','JHN',3,7,'No te maravilles de que te dije: Os es necesario nacer otra vez.',NULL),
('rv1909','JHN',3,8,'El viento de donde quiere sopla, y oyes su sonido; mas ni sabes de dónde viene, ni á dónde vaya: así es todo aquel que es nacido del Espíritu.',NULL),
('rv1909','JHN',3,9,'Respondió Nicodemo, y díjole: ¿Cómo puede esto hacerse?',NULL),
('rv1909','JHN',3,10,'Respondió Jesús, y díjole: ¿Tú eres el maestro de Israel, y no sabes esto?',NULL),
('rv1909','JHN',3,11,'De cierto, de cierto te digo, que lo que sabemos hablamos, y lo que hemos visto, testificamos; y no recibís nuestro testimonio.',NULL),
('rv1909','JHN',3,12,'Si os he dicho cosas terrenas, y no creéis, ¿cómo creeréis si os dijere las celestiales?',NULL),
('rv1909','JHN',3,13,'Y nadie subió al cielo, sino el que descendió del cielo, el Hijo del hombre, que está en el cielo.',NULL),
('rv1909','JHN',3,14,'Y como Moisés levantó la serpiente en el desierto, así es necesario que el Hijo del hombre sea levantado;',NULL),
('rv1909','JHN',3,15,'Para que todo aquel que en él creyere, no se pierda, sino que tenga vida eterna.',NULL),
('rv1909','JHN',3,16,'Porque de tal manera amó Dios al mundo, que ha dado á su Hijo unigénito, para que todo aquel que en él cree, no se pierda, mas tenga vida eterna.',NULL),
('rv1909','JHN',3,17,'Porque no envió Dios á su Hijo al mundo para que condene al mundo, mas para que el mundo sea salvo por él.',NULL),
('rv1909','JHN',3,18,'El que en él cree, no es condenado; mas el que no cree, ya es condenado, porque no creyó en el nombre del unigénito Hijo de Dios.',NULL),
('rv1909','JHN',3,19,'Y esta es la condenación: porque la luz vino al mundo, y los hombres amaron más las tinieblas que la luz; porque sus obras eran malas.',NULL),
('rv1909','JHN',3,20,'Porque todo aquel que hace lo malo, aborrece la luz y no viene á la luz, porque sus obras no sean redargüidas.',NULL),
('rv1909','JHN',3,21,'Mas el que obra verdad, viene á la luz, para que sus obras sean manifestadas que son hechas en Dios.',NULL),
('rv1909','JHN',3,22,'Pasado esto, vino Jesús con sus discípulos á la tierra de Judea; y estaba allí con ellos, y bautizaba.',NULL),
('rv1909','JHN',3,23,'Y bautizaba también Juan en Enón junto á Salim, porque había allí muchas aguas; y venían, y eran bautizados.',NULL),
('rv1909','JHN',3,24,'Porque Juan no había sido aún puesto en la carcel.',NULL),
('rv1909','JHN',3,25,'Y hubo cuestión entre los discípulos de Juan y los Judíos acerca de la purificación.',NULL),
('rv1909','JHN',3,26,'Y vinieron á Juan, y dijéronle: Rabbí, el que estaba contigo de la otra parte del Jordán, del cual tú diste testimonio, he aquí bautiza, y todos vienen á él.',NULL),
('rv1909','JHN',3,27,'Respondió Juan, y dijo: No puede el hombre recibir algo, si no le fuere dado del cielo.',NULL),
('rv1909','JHN',3,28,'Vosotros mismos me sois testigos que dije: Yo no soy el Cristo, sino que soy enviado delante de él.',NULL),
('rv1909','JHN',3,29,'El que tiene la esposa, es el esposo; mas el amigo del esposo, que está en pie y le oye, se goza grandemente de la voz del esposo; así pues, este mi gozo es cumplido.',NULL),
('rv1909','JHN',3,30,'A él conviene crecer, mas á mí menguar.',NULL),
('rv1909','JHN',3,31,'El que de arriba viene, sobre todos es: el que es de la tierra, terreno es, y cosas terrenas habla: el que viene del cielo, sobre todos es.',NULL),
('rv1909','JHN',3,32,'Y lo que vió y oyó, esto testifica: y nadie recibe su testimonio.',NULL),
('rv1909','JHN',3,33,'El que recibe su testimonio, éste signó que Dios es verdadero.',NULL),
('rv1909','JHN',3,34,'Porque el que Dios envió, las palabras de Dios habla: porque no da Dios el Espíritu por medida.',NULL),
('rv1909','JHN',3,35,'El Padre ama al Hijo, y todas las cosas dió en su mano.',NULL),
('rv1909','JHN',3,36,'El que cree en el Hijo, tiene vida eterna; mas el que es incrédulo al Hijo, no verá la vida, sino que la ira de Dios está sobre él.',NULL),
('rv1909','3JN',1,1,'EL anciano al muy amado Gaio, al cual yo amo en verdad.',NULL),
('rv1909','3JN',1,2,'Amado, yo deseo que tú seas prosperado en todas cosas, y que tengas salud, así como tu alma está en prosperidad.',NULL),
('rv1909','3JN',1,3,'Ciertamente me gocé mucho cuando vinieron los hermanos y dieron testimonio de tu verdad, así como tú andas en la verdad.',NULL),
('rv1909','3JN',1,4,'No tengo yo mayor gozo que éste, el oir que mis hijos andan en la verdad.',NULL),
('rv1909','3JN',1,5,'Amado, fielmente haces todo lo que haces para con los hermanos, y con los extranjeros,',NULL),
('rv1909','3JN',1,6,'Los cuales han dado testimonio de tu amor en presencia de la iglesia: á los cuales si ayudares como conviene según Dios, harás bien.',NULL),
('rv1909','3JN',1,7,'Porque ellos partieron por amor de su nombre, no tomando nada de los Gentiles.',NULL),
('rv1909','3JN',1,8,'Nosotros, pues, debemos recibir á los tales, para que seamos cooperadores á la verdad.',NULL),
('rv1909','3JN',1,9,'Yo he escrito á la iglesia: mas Diótrefes, que ama tener el primado entre ellos, no nos recibe.',NULL),
('rv1909','3JN',1,10,'Por esta causa, si yo viniere, recordaré las obras que hace parlando con palabras maliciosas contra nosotros; y no contento con estas cosas, no recibe á los hermanos, y prohibe á los que los quieren [recibir], y los echa de la iglesia.',NULL),
('rv1909','3JN',1,11,'Amado, no sigas lo que es malo, sino lo que es bueno. El que hace bien es de Dios: mas el que hace mal, no ha visto á Dios.',NULL),
('rv1909','3JN',1,12,'Todos dan testimonio de Demetrio, y [aun] la misma verdad: y también nosotros damos testimonio; y vosotros habéis conocido que nuestro testimonio es verdadero.',NULL),
('rv1909','3JN',1,13,'Yo tenía muchas cosas que escribirte; empero no quiero escribirte por tinta y pluma:',NULL),
('rv1909','3JN',1,14,'Porque espero verte en breve, y hablaremos boca á boca. Paz [sea] contigo. Los amigos te saludan. Saluda tú á los amigos por nombre.',NULL),
('rv1909','REV',12,1,'Y UNA grande señal apareció en el cielo: una mujer vestida del sol, y la luna debajo de sus pies, y sobre su cabeza una corona de doce estrellas.',NULL),
('rv1909','REV',12,2,'Y estando preñada, clamaba con dolores de parto, y sufría tormento por parir.',NULL),
('rv1909','REV',12,3,'Y fué vista otra señal en el cielo: y he aquí un grande dragón bermejo, que tenía siete cabezas y diez cuernos, y en sus cabezas siete diademas.',NULL),
('rv1909','REV',12,4,'Y su cola arrastraba la tercera parte de las estrellas del cielo, y las echó en tierra. Y el dragón se paró delante de la mujer que estaba para parir, á fin de devorar á su hijo cuando hubiese parido.',NULL),
('rv1909','REV',12,5,'Y ella parió un hijo varón, el cual había de regir todas las gentes con vara de hierro: y su hijo fué arrebatado para Dios y á su trono.',NULL),
('rv1909','REV',12,6,'Y la mujer huyó al desierto, donde tiene lugar aparejado de Dios, para que allí la mantengan mil doscientos y sesenta días.',NULL),
('rv1909','REV',12,7,'Y fué hecha una grande batalla en el cielo: Miguel y sus ángeles lidiaban contra el dragón; y lidiaba el dragón y sus ángeles,',NULL),
('rv1909','REV',12,8,'Y no prevalecieron, ni su lugar fué más hallado en el cielo.',NULL),
('rv1909','REV',12,9,'Y fué lanzado fuera aquel gran dragón, la serpiente antigua, que se llama Diablo y Satanás, el cual engaña á todo el mundo; fué arrojado en tierra, y sus ángeles fueron arrojados con él.',NULL),
('rv1909','REV',12,10,'Y oí una grande voz en el cielo que decía: Ahora ha venido la salvación, y la virtud, y el reino de nuestro Dios, y el poder de su Cristo; porque el acusador de nuestros hermanos ha sido arrojado, el cual los acusaba delante de nuestro Dios día y noche.',NULL),
('rv1909','REV',12,11,'Y ellos le han vencido por la sangre del Cordero, y por la palabra de su testimonio; y no han amado sus vidas hasta la muerte.',NULL),
('rv1909','REV',12,12,'Por lo cual alegraos, cielos, y los que moráis en ellos. ¡Ay de los moradores de la tierra y del mar! porque el diablo ha descendido á vosotros, teniendo grande ira, sabiendo que tiene poco tiempo.',NULL),
('rv1909','REV',12,13,'Y cuando vió el dragón que él había sido arrojado á la tierra, persiguió á la mujer que había parido al hijo varón.',NULL),
('rv1909','REV',12,14,'Y fueron dadas á la mujer dos alas de grande águila, para que de la presencia de la serpiente volase al desierto, á su lugar, donde es mantenida por un tiempo, y tiempos, y la mitad de un tiempo.',NULL),
('rv1909','REV',12,15,'Y la serpiente echó de su boca tras la mujer agua como un río, á fin de hacer que fuese arrebatada del río.',NULL),
('rv1909','REV',12,16,'Y la tierra ayudó á la mujer, y la tierra abrió su boca, y sorbió el río que había echado el dragón de su boca.',NULL),
('rv1909','REV',12,17,'Entonces el dragón fué airado contra la mujer; y se fué á hacer guerra contra los otros de la simiente de ella, los cuales guardan los mandamientos de Dios, y tienen el testimonio de Jesucristo.',NULL);
INSERT INTO verses_fts (verses_fts) VALUES ('rebuild');
